<?php
/**
 * Bitcoin Pulse 50 — Dashboard BTC/USDT em um único arquivo PHP.
 * 50 indicadores divididos em 5 blocos: tendência, momentum, volume/fluxo,
 * volatilidade/estrutura e derivativos/order book.
 *
 * Fonte: endpoints públicos Binance Spot + USD-M Futures.
 * Requisitos: PHP 8+; cURL recomendado (fallback para file_get_contents).
 */
declare(strict_types=1);
date_default_timezone_set('America/Recife');

$allowedIntervals = ['15m','30m','1h','2h','4h'];
$interval = $_GET['interval'] ?? '1h';
if (!in_array($interval, $allowedIntervals, true)) $interval = '1h';
