function httpJson(string $url, int $timeout = 8): ?array {
    $body = false;
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>$timeout,CURLOPT_USERAGENT=>'BitcoinPulse50/1.0',CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_HTTPHEADER=>['Accept: application/json']]);
        $body = curl_exec($ch); $status = (int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
        if ($body === false || $status < 200 || $status >= 300) $body = false;
    }
    if ($body === false && ini_get('allow_url_fopen')) {
        $ctx = stream_context_create(['http'=>['timeout'=>$timeout,'header'=>"User-Agent: BitcoinPulse50/1.0\r\nAccept: application/json\r\n"],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);
        $body = @file_get_contents($url,false,$ctx);
    }
    if ($body === false) return null;
    $j = json_decode($body,true); return is_array($j)?$j:null;
}
function lastV(array $a): ?float { if(!$a)return null; $v=end($a); return is_numeric($v)?(float)$v:null; }
function clampF(float $v,float $a,float $b): float { return max($a,min($b,$v)); }
function pct(float $a,float $b): float { return $b==0?0:(($a-$b)/$b)*100; }
function smaV(array $a,int $p): ?float { if(count($a)<$p)return null; $s=array_slice($a,-$p); return array_sum($s)/$p; }
function smaSeries(array $a,int $p): array { $n=count($a); $o=array_fill(0,$n,null); if($n<$p)return $o; $sum=0.0; for($i=0;$i<$n;$i++){ $sum+=(float)$a[$i]; if($i>=$p)$sum-=(float)$a[$i-$p]; if($i>=$p-1)$o[$i]=$sum/$p; } return $o; }
function emaSeries(array $a,int $p): array { $n=count($a); if(!$n)return []; $k=2/($p+1); $o=[(float)$a[0]]; for($i=1;$i<$n;$i++)$o[$i]=(float)$a[$i]*$k+$o[$i-1]*(1-$k); return $o; }
function stdDev(array $a): float { $n=count($a); if(!$n)return 0; $m=array_sum($a)/$n; $s=0; foreach($a as $v)$s+=(($v-$m)**2); return sqrt($s/$n); }
function rsiSeries(array $c,int $p=14): array { $n=count($c);$o=array_fill(0,$n,null); if($n<=$p)return $o; $g=0;$l=0; for($i=1;$i<=$p;$i++){ $d=$c[$i]-$c[$i-1]; if($d>=0)$g+=$d; else $l+=-$d; } $ag=$g/$p;$al=$l/$p;$o[$p]=$al==0?100:100-(100/(1+$ag/$al)); for($i=$p+1;$i<$n;$i++){ $d=$c[$i]-$c[$i-1];$gg=max($d,0);$ll=max(-$d,0);$ag=(($ag*($p-1))+$gg)/$p;$al=(($al*($p-1))+$ll)/$p;$o[$i]=$al==0?100:100-(100/(1+$ag/$al)); } return $o; }
function trueRangeSeries(array $h,array $l,array $c): array { $n=count($c);$o=[]; for($i=0;$i<$n;$i++){ if($i===0)$o[]=$h[$i]-$l[$i]; else $o[]=max($h[$i]-$l[$i],abs($h[$i]-$c[$i-1]),abs($l[$i]-$c[$i-1])); } return $o; }
function atrSeries(array $h,array $l,array $c,int $p=14): array { return emaSeries(trueRangeSeries($h,$l,$c),$p); }
function adxDmi(array $h,array $l,array $c,int $p=14): array { $n=count($c);$tr=trueRangeSeries($h,$l,$c);$plus=[];$minus=[]; for($i=0;$i<$n;$i++){ if($i===0){$plus[]=0;$minus[]=0;continue;} $up=$h[$i]-$h[$i-1];$dn=$l[$i-1]-$l[$i];$plus[]=($up>$dn&&$up>0)?$up:0;$minus[]=($dn>$up&&$dn>0)?$dn:0; } $atr=emaSeries($tr,$p);$ep=emaSeries($plus,$p);$em=emaSeries($minus,$p);$dx=[];$pdi=[];$mdi=[]; for($i=0;$i<$n;$i++){ $den=$atr[$i]??0; $pd=$den>0?100*($ep[$i]/$den):0;$md=$den>0?100*($em[$i]/$den):0;$pdi[]=$pd;$mdi[]=$md;$s=$pd+$md;$dx[]=$s>0?100*abs($pd-$md)/$s:0; } $adx=emaSeries($dx,$p); return ['adx'=>$adx,'pdi'=>$pdi,'mdi'=>$mdi]; }
function stochastic(array $h,array $l,array $c,int $p=14,int $smooth=3): array { $n=count($c);$k=array_fill(0,$n,null); for($i=$p-1;$i<$n;$i++){ $hh=max(array_slice($h,$i-$p+1,$p));$ll=min(array_slice($l,$i-$p+1,$p));$k[$i]=($hh-$ll)>0?(($c[$i]-$ll)/($hh-$ll))*100:50; } $tmp=array_map(fn($v)=>$v??50,$k);$d=smaSeries($tmp,$smooth); return ['k'=>$k,'d'=>$d]; }
function cciSeries(array $h,array $l,array $c,int $p=20): array { $n=count($c);$tp=[];$o=array_fill(0,$n,null); for($i=0;$i<$n;$i++)$tp[]=($h[$i]+$l[$i]+$c[$i])/3; for($i=$p-1;$i<$n;$i++){ $s=array_slice($tp,$i-$p+1,$p);$m=array_sum($s)/$p;$md=0;foreach($s as $v)$md+=abs($v-$m);$md/=$p;$o[$i]=$md>0?($tp[$i]-$m)/(0.015*$md):0; } return $o; }
function mfiSeries(array $h,array $l,array $c,array $v,int $p=14): array { $n=count($c);$tp=[];$pos=[];$neg=[];$o=array_fill(0,$n,null); for($i=0;$i<$n;$i++){ $tp[$i]=($h[$i]+$l[$i]+$c[$i])/3; $mf=$tp[$i]*$v[$i]; if($i===0){$pos[$i]=0;$neg[$i]=0;} elseif($tp[$i]>$tp[$i-1]){$pos[$i]=$mf;$neg[$i]=0;} else {$pos[$i]=0;$neg[$i]=$mf;} } for($i=$p;$i<$n;$i++){ $ps=array_sum(array_slice($pos,$i-$p+1,$p));$ns=array_sum(array_slice($neg,$i-$p+1,$p));$o[$i]=$ns==0?100:100-(100/(1+$ps/$ns)); } return $o; }
function obvSeries(array $c,array $v): array { $o=[0.0]; for($i=1,$n=count($c);$i<$n;$i++){ $o[$i]=$o[$i-1]+($c[$i]>$c[$i-1]?$v[$i]:($c[$i]<$c[$i-1]?-$v[$i]:0)); } return $o; }
function adlSeries(array $h,array $l,array $c,array $v): array { $o=[];$adl=0; for($i=0,$n=count($c);$i<$n;$i++){ $r=$h[$i]-$l[$i];$m=$r>0?(($c[$i]-$l[$i])-($h[$i]-$c[$i]))/$r:0;$adl+=$m*$v[$i];$o[]=$adl; } return $o; }
function pvtSeries(array $c,array $v): array { $o=[0.0]; for($i=1,$n=count($c);$i<$n;$i++)$o[$i]=$o[$i-1]+(($c[$i]-$c[$i-1])/$c[$i-1])*$v[$i]; return $o; }
function fmtN(?float $v,int $d=2): string { return $v===null?'—':number_format($v,$d,',','.'); }
function fmtMoney(?float $v): string { return $v===null?'—':'$ '.number_format($v,2,',','.'); }
function addInd(array &$inds,string $cat,string $name,string $value,int $score,string $detail,string $icon='●'): void { $inds[]=['category'=>$cat,'name'=>$name,'value'=>$value,'score'=>max(-2,min(2,$score)),'detail'=>$detail,'icon'=>$icon]; }
function labelMeta(int $s): array { if($s>=1)return ['ALTA','bull']; if($s<=-1)return ['BAIXA','bear']; return ['NEUTRO','neutral']; }

