$opens=$highs=$lows=$closes=$volumes=$quoteVolumes=$takerBuys=$times=[];
foreach($klines as $k){ if(!is_array($k)||count($k)<11)continue; $times[]=(int)$k[0];$opens[]=(float)$k[1];$highs[]=(float)$k[2];$lows[]=(float)$k[3];$closes[]=(float)$k[4];$volumes[]=(float)$k[5];$quoteVolumes[]=(float)$k[7];$takerBuys[]=(float)$k[9]; }

$currentPrice=isset($ticker['lastPrice'])?(float)$ticker['lastPrice']:lastV($closes);
