$inds=[];
if($closes){
    $n=count($closes);$i=$n-1;
    $ema9=emaSeries($closes,9);$ema21=emaSeries($closes,21);$ema50=emaSeries($closes,50);$ema100=emaSeries($closes,100);$ema200=emaSeries($closes,200);
    $sma20=smaSeries($closes,20);$sma50=smaSeries($closes,50);$sma200=smaSeries($closes,200);
    $atr=atrSeries($highs,$lows,$closes,14);$dmi=adxDmi($highs,$lows,$closes,14);
    $rsi14=rsiSeries($closes,14);$rsi7=rsiSeries($closes,7);$stoch=stochastic($highs,$lows,$closes,14,3);$cci=cciSeries($highs,$lows,$closes,20);$mfi=mfiSeries($highs,$lows,$closes,$volumes,14);
    $obv=obvSeries($closes,$volumes);$adl=adlSeries($highs,$lows,$closes,$volumes);$pvt=pvtSeries($closes,$volumes);
    $ema12=emaSeries($closes,12);$ema26=emaSeries($closes,26);$macd=[];for($x=0;$x<$n;$x++)$macd[]=($ema12[$x]??0)-($ema26[$x]??0);$macdSig=emaSeries($macd,9);

    // ----- TENDÊNCIA (1-10) -----
    $e9=lastV($ema9);$e21=lastV($ema21); addInd($inds,'Tendência','EMA 9 × EMA 21',fmtN($e9,0).' / '.fmtN($e21,0),$e9>$e21?2:-2,$e9>$e21?'Curto prazo comprador.':'Curto prazo vendedor.','↗');
    $e50=lastV($ema50);$e200=lastV($ema200); addInd($inds,'Tendência','EMA 50 × EMA 200',fmtN($e50,0).' / '.fmtN($e200,0),$e50>$e200?2:-2,$e50>$e200?'Estrutura principal positiva.':'Estrutura principal negativa.','⌁');
    addInd($inds,'Tendência','Preço × EMA 200',fmtN(pct($currentPrice,$e200),2).'%',$currentPrice>$e200?2:-2,$currentPrice>$e200?'Preço acima da tendência longa.':'Preço abaixo da tendência longa.','₿');
    $s20=lastV($sma20);$s50=lastV($sma50); addInd($inds,'Tendência','SMA 20 × SMA 50',fmtN($s20,0).' / '.fmtN($s50,0),$s20>$s50?1:-1,$s20>$s50?'Média rápida domina.':'Média lenta domina.','∿');
    $sl21=pct($ema21[$i],$ema21[max(0,$i-5)]); addInd($inds,'Tendência','Inclinação EMA 21',fmtN($sl21,2).'%',$sl21>0.15?2:($sl21<-0.15?-2:0),$sl21>0?'Inclinação ascendente.':'Inclinação descendente.','╱');
    $sl50=pct($ema50[$i],$ema50[max(0,$i-10)]); addInd($inds,'Tendência','Inclinação EMA 50',fmtN($sl50,2).'%',$sl50>0.2?2:($sl50<-0.2?-2:0),$sl50>0?'Tendência intermediária ganha altitude.':'Tendência intermediária perde altitude.','╱');
    $adx=lastV($dmi['adx']);$pdi=lastV($dmi['pdi']);$mdi=lastV($dmi['mdi']);$adxScore=($adx??0)>=20?($pdi>$mdi?2:-2):0; addInd($inds,'Tendência','ADX + DMI',fmtN($adx,1).' | +DI '.fmtN($pdi,1),$adxScore,($adx??0)>=20?($pdi>$mdi?'Tendência forte com +DI dominante.':'Tendência forte com -DI dominante.'):'Tendência sem força suficiente.','ADX');
    // Supertrend simplificado por HL2 +/- 3*ATR e direção por preço vs banda média
    $hl2=($highs[$i]+$lows[$i])/2;$a14=$atr[$i]??0;$upBand=$hl2+3*$a14;$loBand=$hl2-3*$a14;$stScore=$currentPrice>$ema21[$i]?1:-1; addInd($inds,'Tendência','Supertrend (proxy ATR)',fmtN($loBand,0).'–'.fmtN($upBand,0),$stScore,$stScore>0?'Preço favorece regime comprador.':'Preço favorece regime vendedor.','ST');
    $tenkan=(max(array_slice($highs,-9))+min(array_slice($lows,-9)))/2;$kijun=(max(array_slice($highs,-26))+min(array_slice($lows,-26)))/2; addInd($inds,'Tendência','Ichimoku Tenkan/Kijun',fmtN($tenkan,0).' / '.fmtN($kijun,0),$tenkan>$kijun?1:-1,$tenkan>$kijun?'Tenkan acima da Kijun.':'Tenkan abaixo da Kijun.','雲');
    $hh55=max(array_slice($highs,-55));$ll55=min(array_slice($lows,-55));$pos55=($hh55-$ll55)>0?($currentPrice-$ll55)/($hh55-$ll55):0.5; addInd($inds,'Tendência','Canal Donchian 55',fmtN($pos55*100,1).'%',$pos55>0.65?1:($pos55<0.35?-1:0),$pos55>0.5?'Preço na metade superior do canal.':'Preço na metade inferior do canal.','▭');

    // ----- MOMENTUM (11-20) -----
    $r14=$rsi14[$i]??null;$r14p=$rsi14[$i-1]??$r14;$rs=0;if($r14!==null){if($r14>=55)$rs=1;elseif($r14<=45)$rs=-1;if($r14<30&&$r14>$r14p)$rs=2;if($r14>70&&$r14<$r14p)$rs=-2;} addInd($inds,'Momentum','RSI 14',fmtN($r14,1),$rs,$rs>0?'Momentum favorece compradores.':($rs<0?'Momentum favorece vendedores.':'Momentum equilibrado.'),'◎');
