    $hist=$macd[$i]-$macdSig[$i]; addInd($inds,'Momentum','MACD Histograma',fmtN($hist,2),$hist>0?2:-2,$hist>0?'Aceleração compradora.':'Aceleração vendedora.','〽');
    $k=$stoch['k'][$i]??null;$d=$stoch['d'][$i]??null; addInd($inds,'Momentum','Stochastic %K/%D',fmtN($k,1).' / '.fmtN($d,1),($k!==null&&$d!==null)?($k>$d?1:-1):0,($k??0)>($d??0)?'%K acima de %D.':'%K abaixo de %D.','%K');
    // Stoch RSI normalizado 14
    $rsivals=array_values(array_filter(array_slice($rsi14,-14),fn($v)=>$v!==null));$srsi=null;if($rsivals){$mn=min($rsivals);$mx=max($rsivals);$srsi=($mx-$mn)>0?(($r14-$mn)/($mx-$mn))*100:50;} addInd($inds,'Momentum','Stoch RSI',fmtN($srsi,1),$srsi>=60?1:($srsi<=40?-1:0),$srsi>=60?'RSI próximo do topo de sua faixa recente.':($srsi<=40?'RSI próximo da base de sua faixa recente.':'Oscilador neutro.'),'SRSI');
    $roc12=pct($closes[$i],$closes[$i-12]); addInd($inds,'Momentum','ROC 12',fmtN($roc12,2).'%', $roc12>0.5?1:($roc12<-0.5?-1:0),$roc12>0?'Taxa de mudança positiva.':'Taxa de mudança negativa.','Δ');
    $cc=lastV($cci); addInd($inds,'Momentum','CCI 20',fmtN($cc,1),$cc>50?1:($cc<-50?-1:0),$cc>50?'CCI confirma força compradora.':($cc<-50?'CCI confirma fraqueza.':'CCI neutro.'),'CCI');
    $hh14=max(array_slice($highs,-14));$ll14=min(array_slice($lows,-14));$wr=($hh14-$ll14)>0?-100*(($hh14-$currentPrice)/($hh14-$ll14)):-50; addInd($inds,'Momentum','Williams %R',fmtN($wr,1),$wr>-50?1:-1,$wr>-50?'Oscilador na metade compradora.':'Oscilador na metade vendedora.','%R');
