    // ----- VOLUME / FLUXO (21-30) -----
    $avgVol20=smaV(array_slice($volumes,0,-1),20)??smaV($volumes,20)??0;$vNow=$volumes[$i];$vr=$avgVol20>0?$vNow/$avgVol20:1;$dir=$closes[$i]>=$opens[$i]?1:-1; addInd($inds,'Volume & Fluxo','Volume relativo',fmtN($vr,2).'×',$vr>=1.2?$dir:0,$vr>=1.2?'Volume acima da média confirma o candle atual.':'Sem expansão relevante de volume.','▥');
