    // ----- VOLATILIDADE / ESTRUTURA (31-40) -----
    $slice20=array_slice($closes,-20);$mid=array_sum($slice20)/20;$sd=stdDev($slice20);$upper=$mid+2*$sd;$lower=$mid-2*$sd;$bbPos=($upper-$lower)>0?($currentPrice-$lower)/($upper-$lower):0.5; addInd($inds,'Volatilidade & Estrutura','Bollinger Position',fmtN($bbPos*100,1).'%', $bbPos>0.6?1:($bbPos<0.4?-1:0),$bbPos>0.5?'Preço na metade superior das bandas.':'Preço na metade inferior.','◉');
    $bbw=($mid>0)?(($upper-$lower)/$mid)*100:0;$oldSlice=array_slice($closes,-40,20);$oldMid=array_sum($oldSlice)/20;$oldBw=$oldMid>0?(4*stdDev($oldSlice)/$oldMid)*100:$bbw;$bbwScore=$bbw>$oldBw*1.08?$dir:0; addInd($inds,'Volatilidade & Estrutura','Bollinger Bandwidth',fmtN($bbw,2).'%', $bbwScore,$bbwScore>0?'Volatilidade expande com alta.':($bbwScore<0?'Volatilidade expande com queda.':'Sem expansão direcional clara.'),'BBW');
    $atrPct=($currentPrice>0)?($atr[$i]/$currentPrice)*100:0;$atrPrev=($closes[$i-10]>0)?($atr[$i-10]/$closes[$i-10])*100:$atrPct;$atrScore=$atrPct>$atrPrev*1.08?$dir:0; addInd($inds,'Volatilidade & Estrutura','ATR 14 %',fmtN($atrPct,2).'%',$atrScore,$atrScore>0?'Volatilidade cresce com candle positivo.':($atrScore<0?'Volatilidade cresce com candle negativo.':'ATR sem sinal direcional forte.'),'ATR');
    $kcMid=$ema21[$i];$kcUp=$kcMid+2*$atr[$i];$kcLo=$kcMid-2*$atr[$i];$kcPos=($kcUp-$kcLo)>0?($currentPrice-$kcLo)/($kcUp-$kcLo):0.5; addInd($inds,'Volatilidade & Estrutura','Keltner Position',fmtN($kcPos*100,1).'%', $kcPos>0.6?1:($kcPos<0.4?-1:0),$kcPos>0.5?'Preço na metade superior do canal.':'Preço na metade inferior do canal.','KC');
    $hhNow=max(array_slice($highs,-10));$hhPrev=max(array_slice($highs,-20,10));$llNow=min(array_slice($lows,-10));$llPrev=min(array_slice($lows,-20,10));$struct=($hhNow>$hhPrev&&$llNow>$llPrev)?2:(($hhNow<$hhPrev&&$llNow<$llPrev)?-2:0); addInd($inds,'Volatilidade & Estrutura','Estrutura HH/HL',($struct>0?'HH + HL':($struct<0?'LH + LL':'Mista')),$struct,$struct>0?'Máximas e mínimas ascendentes.':($struct<0?'Máximas e mínimas descendentes.':'Estrutura mista.'),'HH');
    // Choppiness 14
    $tr14=array_sum(array_slice(trueRangeSeries($highs,$lows,$closes),-14));$range14=max(array_slice($highs,-14))-min(array_slice($lows,-14));$chop=$range14>0?100*log10($tr14/$range14)/log10(14):50;$chopScore=$chop<45?($currentPrice>$ema21[$i]?1:-1):0; addInd($inds,'Volatilidade & Estrutura','Choppiness Index',fmtN($chop,1),$chopScore,$chop<45?'Mercado mais tendencial.':'Mercado mais lateral/choppy.','CH');
    // Realized volatility: std of 20 returns vs previous 20
    $rets=[];for($x=1;$x<$n;$x++)$rets[]=log($closes[$x]/$closes[$x-1]);$rv=stdDev(array_slice($rets,-20))*sqrt(20)*100;$rvOld=stdDev(array_slice($rets,-40,20))*sqrt(20)*100;$rvScore=$rv>$rvOld*1.1?$dir:0; addInd($inds,'Volatilidade & Estrutura','Volatilidade Realizada',fmtN($rv,2).'%',$rvScore,$rvScore>0?'Volatilidade sobe em movimento positivo.':($rvScore<0?'Volatilidade sobe em movimento negativo.':'Sem sinal direcional.'),'RV');
    $body=abs($closes[$i]-$opens[$i]);$range=max($highs[$i]-$lows[$i],0.000001);$bodyPct=$body/$range;$impScore=$bodyPct>0.65?$dir:0; addInd($inds,'Volatilidade & Estrutura','Impulso do Candle',fmtN($bodyPct*100,1).'%',$impScore,$impScore>0?'Candle comprador de corpo forte.':($impScore<0?'Candle vendedor de corpo forte.':'Candle sem corpo dominante.'),'▮');
    $hh20=max(array_slice($highs,-20));$ll20=min(array_slice($lows,-20));$pos20=($hh20-$ll20)>0?($currentPrice-$ll20)/($hh20-$ll20):0.5; addInd($inds,'Volatilidade & Estrutura','Posição no Range 20',fmtN($pos20*100,1).'%', $pos20>0.7?1:($pos20<0.3?-1:0),$pos20>0.5?'Preço próximo da metade superior.':'Preço próximo da metade inferior.','R20');
    $ret3=pct($closes[$i],$closes[$i-3]);$ret12=pct($closes[$i],$closes[$i-12]);$align=($ret3>0&&$ret12>0)?1:(($ret3<0&&$ret12<0)?-1:0); addInd($inds,'Volatilidade & Estrutura','Alinhamento 3 × 12 candles',fmtN($ret3,2).'% / '.fmtN($ret12,2).'%',$align,$align>0?'Curtíssimo e curto prazo alinhados em alta.':($align<0?'Curtíssimo e curto prazo alinhados em baixa.':'Horizontes divergentes.'),'3×12');

    // ----- DERIVATIVOS / ORDER BOOK (41-50) -----
    $bidNot=0;$askNot=0;$bidTop5=0;$askTop5=0;$nearBid=0;$nearAsk=0;$bestBid=null;$bestAsk=null;
    if(isset($depth['bids'],$depth['asks'])){
        foreach($depth['bids'] as $idx=>$r){$p=(float)$r[0];$q=(float)$r[1];$not=$p*$q;$bidNot+=$not;if($idx<5)$bidTop5+=$not;if($currentPrice>0&&(($currentPrice-$p)/$currentPrice)<=0.0025)$nearBid+=$not;if($idx===0)$bestBid=$p;}
        foreach($depth['asks'] as $idx=>$r){$p=(float)$r[0];$q=(float)$r[1];$not=$p*$q;$askNot+=$not;if($idx<5)$askTop5+=$not;if($currentPrice>0&&(($p-$currentPrice)/$currentPrice)<=0.0025)$nearAsk+=$not;if($idx===0)$bestAsk=$p;}
    }
    $book=($bidNot+$askNot)>0?$bidNot/($bidNot+$askNot):0.5; addInd($inds,'Derivativos & Book','Order Book Imbalance',fmtN($book*100,1).'% bids',$book>0.55?2:($book<0.45?-2:0),$book>0.55?'Profundidade favorece bids.':($book<0.45?'Profundidade favorece asks.':'Book equilibrado.'),'≋');
    $spread=($bestBid&&$bestAsk)?(($bestAsk-$bestBid)/$currentPrice)*100:null;$spreadScore=0;if($spread!==null&&$spread<0.01)$spreadScore=$dir>0?1:-1; addInd($inds,'Derivativos & Book','Bid/Ask Spread',$spread===null?'—':fmtN($spread,4).'%', $spreadScore,$spread!==null&&$spread<0.01?'Spread muito estreito; execução eficiente, direção segue fluxo atual.':'Spread sem sinal direcional forte.','↔');
    $wall=($bidTop5+$askTop5)>0?$bidTop5/($bidTop5+$askTop5):0.5; addInd($inds,'Derivativos & Book','Walls Top 5',fmtN($wall*100,1).'% bids',$wall>0.58?1:($wall<0.42?-1:0),$wall>0.58?'Maior parede compradora próxima.':($wall<0.42?'Maior parede vendedora próxima.':'Paredes equilibradas.'),'▰');
    $near=($nearBid+$nearAsk)>0?$nearBid/($nearBid+$nearAsk):0.5; addInd($inds,'Derivativos & Book','Depth ±0,25%',fmtN($near*100,1).'% bids',$near>0.55?1:($near<0.45?-1:0),$near>0.55?'Liquidez próxima favorece compras.':($near<0.45?'Liquidez próxima favorece vendas.':'Liquidez próxima equilibrada.'),'±');
    $fund=isset($premium['lastFundingRate'])?(float)$premium['lastFundingRate']:null;$fundPct=$fund!==null?$fund*100:null;$fs=0;$fd='Funding neutro.';if($fund!==null){if($fund>0.0005){$fs=-1;$fd='Longs congestionados; risco contrarian.';}elseif($fund<-0.0003){$fs=1;$fd='Shorts congestionados; risco de squeeze.';}elseif($fund>0){$fs=1;$fd='Leve viés long.';}elseif($fund<0){$fs=-1;$fd='Leve viés short.';}} addInd($inds,'Derivativos & Book','Funding Rate',fmtN($fundPct,4).'%',$fs,$fd,'ƒ');
    $oiChange=null;$oiTrend=null;if(is_array($oiHist)&&count($oiHist)>=2){$a=$oiHist[count($oiHist)-2];$b=$oiHist[count($oiHist)-1];$old=(float)($a['sumOpenInterestValue']??$a['sumOpenInterest']??0);$new=(float)($b['sumOpenInterestValue']??$b['sumOpenInterest']??0);if($old>0)$oiChange=pct($new,$old);$first=$oiHist[0];$f=(float)($first['sumOpenInterestValue']??$first['sumOpenInterest']??0);if($f>0)$oiTrend=pct($new,$f);} $pchg=pct($closes[$i],$closes[$i-1]);$ois=0;if($oiChange!==null&&abs($oiChange)>0.3)$ois=$pchg>0?2:-2; addInd($inds,'Derivativos & Book','Open Interest + Preço',$oiChange===null?'—':fmtN($oiChange,2).'%',$ois,$ois>0?'OI cresce junto da alta.':($ois<0?'OI cresce junto da queda.':'OI sem confirmação forte.'),'∞');
    $oitScore=$oiTrend!==null?($oiTrend>0.8?1:($oiTrend<-0.8?-1:0)):0; addInd($inds,'Derivativos & Book','Open Interest Trend',$oiTrend===null?'—':fmtN($oiTrend,2).'%',$oitScore,$oitScore>0?'Alavancagem agregada aumenta.':($oitScore<0?'Alavancagem agregada diminui.':'OI relativamente estável.'),'OI');
    $mark=isset($premium['markPrice'])?(float)$premium['markPrice']:null;$index=isset($premium['indexPrice'])?(float)$premium['indexPrice']:null;$basis=($mark&&$index)?pct($mark,$index):null;$bs=0;if($basis!==null){if($basis>0.03)$bs=1;elseif($basis<-0.03)$bs=-1;} addInd($inds,'Derivativos & Book','Basis Mark × Index',$basis===null?'—':fmtN($basis,4).'%',$bs,$bs>0?'Futuros negociam com prêmio.':($bs<0?'Futuros negociam com desconto.':'Basis próximo do neutro.'),'BAS');
    $glr=null;if(is_array($globalLS)&&$globalLS){$row=end($globalLS);$glr=isset($row['longShortRatio'])?(float)$row['longShortRatio']:null;} $gls=0;if($glr!==null){if($glr>1.8)$gls=-1;elseif($glr>1.05)$gls=1;elseif($glr<0.6)$gls=1;elseif($glr<0.95)$gls=-1;} addInd($inds,'Derivativos & Book','Global Long/Short Ratio',$glr===null?'—':fmtN($glr,2),$gls,$glr===null?'Dados indisponíveis.':($glr>1.8?'Longs excessivamente congestionados.':($glr<0.6?'Shorts excessivamente congestionados.':($glr>=1?'Mais contas long.':'Mais contas short.'))),'L/S');
    $tlr=null;if(is_array($topPosLS)&&$topPosLS){$row=end($topPosLS);$tlr=isset($row['longShortRatio'])?(float)$row['longShortRatio']:null;} $tls=0;if($tlr!==null){if($tlr>2)$tls=-1;elseif($tlr>1.05)$tls=1;elseif($tlr<0.55)$tls=1;elseif($tlr<0.95)$tls=-1;} addInd($inds,'Derivativos & Book','Top Traders Position Ratio',$tlr===null?'—':fmtN($tlr,2),$tls,$tlr===null?'Dados indisponíveis.':($tlr>2?'Top traders muito carregados em longs.':($tlr<0.55?'Top traders muito carregados em shorts.':($tlr>=1?'Top traders líquidos em long.':'Top traders líquidos em short.'))),'TOP');
}

// Score por categoria para reduzir dupla contagem entre indicadores correlacionados.
$categoryOrder=['Tendência','Momentum','Volume & Fluxo','Volatilidade & Estrutura','Derivativos & Book'];
$categoryScores=[];$categoryCounts=[];
foreach($categoryOrder as $cat){$vals=array_values(array_filter($inds,fn($x)=>$x['category']===$cat));$sum=array_sum(array_map(fn($x)=>(int)$x['score'],$vals));$max=max(1,count($vals)*2);$categoryScores[$cat]=($sum/$max)*100;$categoryCounts[$cat]=count($vals);}
$overall=count($inds)?array_sum($categoryScores)/count($categoryScores):0;
$scorePct=(int)round(clampF($overall,-100,100));
if($scorePct>=30){$bias='VIÉS DE ALTA';$biasClass='bull';$summary='A maioria dos blocos está alinhada a favor dos compradores.';} elseif($scorePct<=-30){$bias='VIÉS DE BAIXA';$biasClass='bear';$summary='A maioria dos blocos está alinhada a favor dos vendedores.';} else {$bias='MERCADO MISTO';$biasClass='neutral';$summary='Há divergências entre os grupos; convicção insuficiente.';}
$bullCount=count(array_filter($inds,fn($x)=>$x['score']>=1));$bearCount=count(array_filter($inds,fn($x)=>$x['score']<=-1));$neutralCount=count($inds)-$bullCount-$bearCount;

$spark=array_slice($closes,-90);$sparkPoints='';if($spark){$mn=min($spark);$mx=max($spark);$rg=max($mx-$mn,0.000001);$nn=count($spark);foreach($spark as $ix=>$v){$x=$nn<=1?0:($ix/($nn-1))*700;$y=150-(($v-$mn)/$rg)*120-15;$sparkPoints.=number_format($x,1,'.','').','.number_format($y,1,'.','').' ';}}
$updatedAt=date('d/m/Y H:i:s');
?>
