gauge-wrap{display:flex;gap:24px;align-items:center}.gauge{width:155px;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;position:relative;background:conic-gradient(var(--gc) calc(var(--p)*1%),rgba(255,255,255,.07) 0)}.gauge:before{content:"";position:absolute;inset:14px;border-radius:50%;background:#0f1b29}.inside{position:relative;text-align:center}.inside strong{font-size:34px;display:block}.bias{font-size:26px;font-weight:900}.pills{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:18px}.pill{padding:12px;border-radius:14px;background:rgba(255,255,255,.035);text-align:center}.pill b{font-size:20px;display:block}.pill span{font-size:10px;text-transform:uppercase;color:var(--muted)}.category-bars{display:grid;gap:9px;margin-top:18px}.catrow{display:grid;grid-template-columns:175px 1fr 55px;gap:10px;align-items:center;font-size:12px}.track{height:7px;background:rgba(255,255,255,.06);border-radius:8px;position:relative;overflow:hidden}.track:after{content:"";position:absolute;left:50%;top:0;bottom:0;width:1px;background:rgba(255,255,255,.16)}.fill{position:absolute;top:0;bottom:0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:14px;margin:30px 0 14px}.section-head h2{margin:0}.section-head p{margin:0;color:var(--muted);font-size:12px}.group-title{margin:26px 0 12px;display:flex;align-items:center;gap:10px}.group-title h3{margin:0;font-size:18px}.group-title span{font-size:11px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:13px}.indicator{padding:17px;min-height:196px;position:relative}.row{display:flex;justify-content:space-between;gap:8px}.icon{width:36px;height:36px;border-radius:11px;background:rgba(255,255,255,.055);display:grid;place-items:center;font-size:13px;font-weight:900}.badge{padding:7px 9px;border-radius:999px;font-size:10px;font-weight:900}.badge.bull{color:var(--bull);background:rgba(39,230,161,.12)}.badge.bear{color:var(--bear);background:rgba(255,95,115,.1